def _make_filter_catalog(key: str, subtype: str, name: str, spec: str, wega_sku: str, mann_sku: str, mahle_sku: str) -> dict:
    return {
        "key": key,
        "category": "FILTRO",
        "subtype": subtype,
        "name": name,
        "specification": spec,
        "ecoBrand": "Wega / Tecfil",
        "ecoName": f"{name} — Ref. {wega_sku}",
        "ecoSku": wega_sku,
        "bestBrand": "Mann-Filter",
        "bestName": f"{name} OEM — Ref. {mann_sku}",
        "bestSku": mann_sku,
        "premBrand": "Mahle / Bosch",
        "premName": f"{name} Premium — Ref. {mahle_sku}",
        "premSku": mahle_sku,
    }


